import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.MultivaluedMap;
import javax.ws.rs.ext.MessageBodyReader;
import javax.ws.rs.ext.MessageBodyWriter;

import org.apache.abdera.Abdera;
import org.apache.abdera.model.Document;
import org.apache.abdera.model.Element;
import org.apache.abdera.parser.Parser;
import org.apache.abdera.parser.ParserOptions;

/**
 * Secure implementation of an Atom provider.
 *
 * <p>
 * The original implementation reused a shared {@link Parser} instance and
 * configured the {@link ParserOptions} inside a synchronized block.  Because the
 * parser is mutable, another thread could invoke {@code parse(...)} before the
 * options were applied, re‑enabling entity resolution and opening an XXE
 * vulnerability.
 * </p>
 *
 * <p>
 * This patched version creates a fresh {@link Parser} for each request and
 * supplies a dedicated {@link ParserOptions} instance that explicitly disables
 * entity resolution and entity expansion before any parsing occurs.  The
 * {@code InputStream} is also closed via a try‑with‑resources block to avoid
 * resource leaks.
 * </p>
 */
public abstract class AbstractAtomProvider<T extends Element>
        implements MessageBodyWriter<T>, MessageBodyReader<T> {

    private static final Abdera ATOM_ENGINE = new Abdera();
    private boolean autodetectCharset;

    // ----------------------------------------------------------------------
    //  Secure readFrom implementation
    // ----------------------------------------------------------------------
    @Override
    public T readFrom(Class<T> clazz,
                      Type type,
                      Annotation[] annotations,
                      MediaType mediaType,
                      MultivaluedMap<String, String> httpHeaders,
                      InputStream entityStream) throws IOException {

        // Create a new parser for this request – no shared mutable state.
        Parser parser = ATOM_ENGINE.getParser();

        // Build a fresh, immutable set of parser options.
        ParserOptions options = new ParserOptions();
        options.setAutodetectCharset(autodetectCharset);
        // Disable all forms of external entity processing.
        options.setResolveEntities(false);          // Prevent external entity resolution.
        options.setExpandEntityReferences(false);  // Prevent expansion of any entity references.
        // (If the Abdera version supports it, you could also call
        // options.setSupportDTD(false) to reject DTDs outright.)

        // Parse the input using the securely configured options.
        // The parse method that accepts ParserOptions guarantees the options are
        // applied before any XML processing begins.
        Document<T> doc;
        try (InputStream is = entityStream) {
            doc = parser.parse(is, options);
        }

        // The document root is the desired Element instance.
        return doc.getRoot();
    }

    // other methods (writeTo, etc.) remain unchanged
}
