import java.io.File;
import java.io.IOException;

public class ImportingUtilities {

    // other methods

    /**
     * Allocates a file inside {@code dir} using the supplied {@code name}.
     * The method sanitises the {@code name} to prevent directory‑traversal attacks.
     *
     * @param dir  the directory in which the file must be created (must not be {@code null})
     * @param name the requested file name (may contain a query part after {@code ?})
     * @return a {@link File} that does not yet exist and is guaranteed to be located
     *         inside {@code dir}
     * @throws IllegalArgumentException if {@code dir} or {@code name} is {@code null},
     *                                  empty, or would resolve outside {@code dir}
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null) {
            throw new IllegalArgumentException("Target directory must not be null");
        }
        if (name == null) {
            throw new IllegalArgumentException("File name must not be null");
        }

        // Strip any URL‑style query string (e.g. \"file.txt?foo=bar\")
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Normalise the name – remove leading separators to avoid absolute paths
        while (name.startsWith("/") || name.startsWith("\\")) {
            name = name.substring(1);
        }

        // Build the initial candidate file
        File candidate = new File(dir, name);
        candidate = ensureInsideBaseDir(dir, candidate);

        // Split the name into prefix / suffix for the collision‑resolution loop
        int dot = name.lastIndexOf('.');
        String prefix = (dot < 0) ? name : name.substring(0, dot);
        String suffix = (dot < 0) ? "" : name.substring(dot);
        int index = 2;

        // If a file with the same name already exists, append a numeric suffix
        while (candidate.exists()) {
            String newName = prefix + "-" + index++ + suffix;
            candidate = new File(dir, newName);
            candidate = ensureInsideBaseDir(dir, candidate);
        }

        // Create any missing parent directories (still inside {@code dir})
        File parent = candidate.getParentFile();
        if (parent != null && !parent.mkdirs() && !parent.isDirectory()) {
            throw new IllegalArgumentException("Unable to create directory structure for " + candidate);
        }

        return candidate;
    }

    /**
     * Verifies that {@code file} resolves to a location that is a descendant of {@code baseDir}.
     * The check is performed using canonical paths to neutralise \"..\" and symbolic links.
     *
     * @throws IllegalArgumentException if the resolved path is outside {@code baseDir}
     */
    private static File ensureInsideBaseDir(File baseDir, File file) {
        try {
            String basePath = baseDir.getCanonicalPath();
            if (!basePath.endsWith(File.separator)) {
                basePath = basePath + File.separator;
            }
            String filePath = file.getCanonicalPath();
            if (!filePath.startsWith(basePath)) {
                throw new IllegalArgumentException(
                        "Invalid file name – path traversal detected: " + filePath);
            }
            return file;
        } catch (IOException e) {
            throw new IllegalArgumentException("Failed to resolve file paths", e);
        }
    }

    // other methods

}
