    /** Whitelist pattern for locale strings: language[_country[_variant]] */
    private static final Pattern LOCALE_PATTERN = Pattern.compile(
            "^[a-zA-Z]{2,3}" +               // language (2‑3 letters)
            "(?:_[a-zA-Z]{2})?" +            // optional country (2 letters)
            "(?:_[a-zA-Z0-9]+)?$"            // optional variant (alphanum)
    );

    /** Maximum allowed length for a locale string – prevents excessively long payloads. */
    private static final int MAX_LOCALE_LENGTH = 20;

    // -----------------------------------------------------------------------
    // Other interceptor methods (omitted for brevity)
    // -----------------------------------------------------------------------

    /**
     * Creates a {@link Locale} object from the request parameter, which might
     * already be a {@link Locale} or a {@link String}. The input is validated
     * against a whitelist to avoid processing malicious data.
     *
     * @param requestedLocale the parameter from the request
     * @return a {@link Locale} instance if the input is valid; {@code null} otherwise
     */
    protected Locale getLocaleFromParam(Object requestedLocale) {
        if (requestedLocale == null) {
            return null;
        }

        // If the caller already supplied a Locale instance, trust it (Locale is immutable and safe).
        if (requestedLocale instanceof Locale) {
            Locale locale = (Locale) requestedLocale;
            LOG.debug("Applied request locale: {}", locale);
            return locale;
        }

        // Convert to String and trim whitespace.
        String localeStr = requestedLocale.toString().trim();

        // Basic sanity checks.
        if (localeStr.isEmpty()) {
            LOG.debug("Requested locale string is empty after trimming.");
            return null;
        }
        if (localeStr.length() > MAX_LOCALE_LENGTH) {
            LOG.warn("Requested locale string exceeds maximum length ({}): {}", MAX_LOCALE_LENGTH, localeStr);
            return null;
        }

        // Validate against the whitelist pattern.
