        if (locale != null) {
            LOG.debug("Applied request locale: {}", locale);
        } else {
            LOG.warn("Unable to parse locale from validated string: {}", localeStr);
        }
        return locale;
    }

    // -----------------------------------------------------------------------
    // Remaining interceptor implementation (omitted for brevity)
    // -----------------------------------------------------------------------
