        env.put(Context.PROVIDER_URL, jndiLdapContextFactory.getUrl());

        InitialLdapContext ctx = null;
        StartTlsResponse tls = null;
        boolean bindSucceeded = false; // tracks successful authentication

        try {
            // -----------------------------------------------------------------
            // 3. Establish an unauthenticated connection.
            // -----------------------------------------------------------------
            ctx = new InitialLdapContext(env, null);

            // -----------------------------------------------------------------
            // 4. Upgrade the connection to TLS before any credentials travel.
            // -----------------------------------------------------------------
            StartTlsRequest startTlsRequest = new StartTlsRequest();
            tls = (StartTlsResponse) ctx.extendedOperation(startTlsRequest);
            tls.negotiate(); // throws IOException on failure

