            ctx.addToEnvironment(Context.SECURITY_PRINCIPAL, principal);
            ctx.addToEnvironment(Context.SECURITY_CREDENTIALS, credentials);

            // -----------------------------------------------------------------
            // 6. Force an explicit bind to verify the supplied credentials.
            // -----------------------------------------------------------------
            ctx.reconnect(null); // triggers a bind; throws AuthenticationException on bad creds
