import javax.xml.transform.TransformerFactory;
import javax.xml.transform.stream.StreamSource;

/**
 * Secure implementation of XSLT rendering.
 */
public class XsltRenderer implements Renderer {

    // -----------------------------------------------------------------------
    // Secure creation of a Transformer from an XSLT template stream
    // -----------------------------------------------------------------------
    /**
     * Creates a {@link Transformer} from the supplied XSLT {@code InputStream}
     * while applying strict security hardening:
     * <ul>
     *   <li>Enables {@code FEATURE_SECURE_PROCESSING} to limit resource usage.</li>
     *   <li>Disables access to external DTDs and stylesheets to prevent XXE/RCE.</li>
     *   <li>Validates the input stream is non‑null.</li>
     *   <li>Uses try‑with‑resources to guarantee the stream is closed safely.</li>
     * </ul>
     *
     * @param templateStream the XSLT template; must not be {@code null}
     * @return a securely configured {@link Transformer}
     * @throws IOException if an I/O error occurs while reading the stream
     * @throws ProcessingFailedException if the XSLT cannot be compiled
     */
    private static Transformer createTransformer(InputStream templateStream) throws IOException {
        if (templateStream == null) {
            throw new IllegalArgumentException("templateStream must not be null");
        }

        // A fresh factory per call guarantees that our security settings cannot be
        // overridden elsewhere in the application.
        TransformerFactory factory = TransformerFactory.newInstance();

        // -------------------------------------------------------------------
        // Harden the factory against malicious XSLT
        // -------------------------------------------------------------------
        // 1. Enable secure processing (limits CPU/memory usage, disables
        //    extensions that could execute arbitrary code).
        try {
            factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
        } catch (TransformerConfigurationException e) {
            // If the implementation does not support the feature, fail fast.
            throw new ProcessingFailedException("Secure processing feature not supported", e);
        }

        // 2. Block any external entity or stylesheet access.
        //    Empty strings mean "no access".
        try {
            factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD, "");
            factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_STYLESHEET, "");
        } catch (IllegalArgumentException e) {
            // Some factories may not support these attributes; treat it as a
            // configuration error because allowing external access is unsafe.
            throw new ProcessingFailedException("Factory does not support external access restrictions", e);
        }

        // -------------------------------------------------------------------
        // Build the transformer safely
        // -------------------------------------------------------------------
        try (InputStream is = templateStream) {
            return factory.newTransformer(new StreamSource(is));
        } catch (TransformerConfigurationException e) {
            // Wrap the checked exception in the domain‑specific unchecked one.
            throw new ProcessingFailedException("Failed to create XSLT transformer", e);
        }
    }

    // -----------------------------------------------------------------------
    // Other methods of the class (omitted for brevity)
    // -----------------------------------------------------------------------
}
