        } else if (body instanceof BeanInvocation) {
            BeanInvocation bi = exchange.getContext()
                                        .getTypeConverter()
                                        .convertTo(BeanInvocation.class, exchange, body);
            if (bi.getArgs() != null && bi.getArgs().length == 1 && bi.getArgs()[0] == null) {
                return null; // nothing to parse
            }
        } else if (body instanceof String) {
            inputSource = new InputSource(new StringReader((String) body));
        } else if (body instanceof InputSource) {
            inputSource = (InputSource) body;
        }

        // -----------------------------------------------------------------
        // 3. If we have an InputSource, parse it with a securely configured
        //    DocumentBuilderFactory to eliminate XXE vectors.
        // -----------------------------------------------------------------
        if (inputSource != null) {
            DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();

            // ---- Secure XML processing features (XXE mitigation) ----
            dbf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
            // Disallow DOCTYPE declarations
            dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
            // Disable external general entities
            dbf.setFeature("http://xml.org/sax/features/external-general-entities", false);
            // Disable external parameter entities
            dbf.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
            // No XInclude
            dbf.setXIncludeAware(false);
            // Do not expand entity references
            dbf.setExpandEntityReferences(false);
            // Preserve namespace handling as configured on this builder
            dbf.setNamespaceAware(isNamespaceAware());

            DocumentBuilder builder = dbf.newDocumentBuilder();

            // Prevent the parser from trying to resolve any external entities
            builder.setEntityResolver((publicId, systemId) -> new InputSource(new StringReader("")));

            Document doc = builder.parse(inputSource);
            // If a specific document type was requested (e.g., a subclass of Document),
            // attempt a conversion now that we have a safe Document instance.
