import org.apache.commons.io.IOUtils;
import org.cloudfoundry.identity.uaa.scim.ScimUser;
import org.cloudfoundry.identity.uaa.scim.ScimUserProvisioning;
import org.cloudfoundry.identity.uaa.scim.exception.ScimResourceNotFoundException;
import org.cloudfoundry.identity.uaa.util.JsonUtils;
import org.cloudfoundry.identity.uaa.util.UaaUrlUtils;
import org.cloudfoundry.identity.uaa.zone.IdentityZoneHolder;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.GrantedAuthority;
import org.springframework.security.core.context.SecurityContextHolder;

import javax.servlet.http.HttpServletRequest;
import java.io.IOException;
import java.util.Collection;

public class ScimUserSelfUpdateAllowed {

    public static final int USER_ID_PATH_PARAMETER_INDEX = 1;
    private ScimUserProvisioning scimUserProvisioning;

    // -----------------------------------------------------------------------
    // Core authorization logic
    // -----------------------------------------------------------------------
    public boolean isAllowed(HttpServletRequest request) throws IOException {

        /* ---------------------------------------------------------------
         * 1. Verify that the request originates from an authenticated principal.
         * --------------------------------------------------------------- */
        Authentication auth = SecurityContextHolder.getContext().getAuthentication();
        if (auth == null || !auth.isAuthenticated()) {
            return false;
        }

        /* ---------------------------------------------------------------
         * 2. Extract the target user identifier from the request URL.
         * --------------------------------------------------------------- */
        String targetUserId = UaaUrlUtils.extractPathVariableFromUrl(
                USER_ID_PATH_PARAMETER_INDEX,
                UaaUrlUtils.getRequestPath(request));

        /* ---------------------------------------------------------------
         * 3. Determine if the caller is an administrator.  Administrators
         *    are allowed to modify any user; non‑admins must act on their
         *    own account.
         * --------------------------------------------------------------- */
        boolean isAdmin = hasAuthority(auth.getAuthorities(), "uaa.admin");

        if (!isAdmin) {
            String callerUserId = resolveUserIdFromPrincipal(auth.getPrincipal());
            if (callerUserId == null || !callerUserId.equals(targetUserId)) {
                // Caller is neither admin nor the owner of the account.
                return false;
            }
        }

        /* ---------------------------------------------------------------
         * 4. Parse the request body safely.
         * --------------------------------------------------------------- */
        String requestBody = IOUtils.toString(request.getReader());
        if (requestBody == null || requestBody.trim().isEmpty()) {
            return false;
        }

        ScimUser scimUserFromRequest = JsonUtils.readValue(requestBody, ScimUser.class);
        if (scimUserFromRequest == null) {
            return false;
        }

        /* ---------------------------------------------------------------
         * 5. Load the persisted user record.
         * --------------------------------------------------------------- */
        String zoneId = IdentityZoneHolder.get().getId();
        ScimUser scimUserFromDb;
        try {
            scimUserFromDb = scimUserProvisioning.retrieve(targetUserId, zoneId);
        } catch (ScimResourceNotFoundException e) {
            // If the user does not exist we must not allow an update.
            return false;
        }

        /* ---------------------------------------------------------------
         * 6. Compare immutable fields – any change to these fields is
         *    considered a forbidden operation for a self‑update.
         * --------------------------------------------------------------- */
        if (!safeEquals(scimUserFromDb.getPrimaryEmail(), scimUserFromRequest.getPrimaryEmail())) {
            return false;
        }
        if (!safeEquals(scimUserFromDb.getUserName(), scimUserFromRequest.getUserName())) {
            return false;
        }
        if (scimUserFromDb.isVerified() != scimUserFromRequest.isVerified()) {
            return false;
        }
        if (scimUserFromDb.isActive() != scimUserFromRequest.isActive()) {
            return false;
        }
        if (!safeEquals(scimUserFromDb.getOrigin(), scimUserFromRequest.getOrigin())) {
            return false;
        }

        // All checks passed – the operation is allowed.
        return true;
    }

    // -----------------------------------------------------------------------
    // Helper utilities
    // -----------------------------------------------------------------------

    /**
     * Safely compare two objects, handling {@code null} values.
     */
    private static boolean safeEquals(Object a, Object b) {
        return (a == null) ? b == null : a.equals(b);
    }

    /**
     * Determine whether the supplied collection of authorities contains the
     * required authority.
     */
    private static boolean hasAuthority(Collection<? extends GrantedAuthority> authorities,
                                         String requiredAuthority) {
        if (authorities == null) {
            return false;
        }
        for (GrantedAuthority ga : authorities) {
            if (requiredAuthority.equals(ga.getAuthority())) {
                return true;
            }
        }
        return false;
    }

    /**
     * Resolve the user identifier from the authentication principal.
     * The principal may be a simple {@code String} (the user id) or a
     * custom object exposing a {@code getId()} method.
     */
    private static String resolveUserIdFromPrincipal(Object principal) {
        if (principal instanceof String) {
            return (String) principal;
        }
        try {
            // Attempt to call a conventional getId() method via reflection.
            java.lang.reflect.Method getIdMethod = principal.getClass().getMethod("getId");
            Object id = getIdMethod.invoke(principal);
            return (id != null) ? id.toString() : null;
        } catch (Exception ignored) {
            // If reflection fails we cannot determine the caller's id.
            return null;
        }
    }

    // -----------------------------------------------------------------------
    // Setters / Dependency injection (omitted for brevity)
    // -----------------------------------------------------------------------
    public void setScimUserProvisioning(ScimUserProvisioning scimUserProvisioning) {
        this.scimUserProvisioning = scimUserProvisioning;
    }
}
